# GraphQL query — get a user and their posts, but only the fields you need
query {
  user(id: 1) {
    name
    email
    posts {
      title
      publishedAt
    }
  }
}

# The response matches the query's shape exactly
# {
#   "user": {
#     "name": "Ada",
#     "email": "ada@example.com",
#     "posts": [
#       { "title": "Hello World", "publishedAt": "2024-01-15" }
#     ]
#   }
# }

# Schema Definition Language (SDL)

# Object type — a User has these fields
type User {
  id: ID!
  name: String!
  email: String!
  age: Int
  posts: [Post!]!
}

# Another object type
type Post {
  id: ID!
  title: String!
  content: String!
  author: User!
  publishedAt: String
}

# The Query type — defines all read operations
type Query {
  user(id: ID!): User
  users(limit: Int = 10): [User!]!
  posts(authorId: ID): [Post!]!
}

# The Mutation type — defines all write operations
type Mutation {
  createUser(input: CreateUserInput!): User!
  updateUser(id: ID!, input: UpdateUserInput!): User!
  deleteUser(id: ID!): Boolean!
}

# Input type — for mutation arguments
input CreateUserInput {
  name: String!
  email: String!
  age: Int
}

input UpdateUserInput {
  name: String
  email: String
  age: Int
}

# Enum — a field with a fixed set of values
enum PostStatus {
  DRAFT
  PUBLISHED
  ARCHIVED
}

// npm install @apollo/server graphql
import { ApolloServer } from '@apollo/server';
import { startStandaloneServer } from '@apollo/server/standalone';

// 1. Define the schema (typeDefs)
const typeDefs = `#graphql
  type User {
    id: ID!
    name: String!
    email: String!
    posts: [Post!]!
  }

  type Post {
    id: ID!
    title: String!
    author: User!
  }

  type Query {
    user(id: ID!): User
    users: [User!]!
  }
`;

// 2. Mock data
const users = [
  { id: '1', name: 'Ada', email: 'ada@example.com' },
  { id: '2', name: 'Grace', email: 'grace@example.com' },
];
const posts = [
  { id: '1', title: 'Hello World', authorId: '1' },
  { id: '2', title: 'GraphQL Rocks', authorId: '1' },
];

// 3. Write resolvers — one function per field
const resolvers = {
  Query: {
    user: (_, { id }) => users.find(u => u.id === id),
    users: () => users,
  },
  // Field resolver: resolve 'posts' on a User
  User: {
    posts: (parent) => posts.filter(p => p.authorId === parent.id),
  },
  // Field resolver: resolve 'author' on a Post
  Post: {
    author: (parent) => users.find(u => u.id === parent.authorId),
  },
};

// 4. Start the server
const server = new ApolloServer({ typeDefs, resolvers });
const { url } = await startStandaloneServer(server, { listen: { port: 4000 } });
console.log(`GraphQL API ready at ${url}`);

// Server: mutation resolver
const typeDefs = `#graphql
  type Mutation {
    createPost(input: CreatePostInput!): Post!
  }
  input CreatePostInput {
    title: String!
    content: String!
  }
`;

const resolvers = {
  Mutation: {
    createPost: (_, { input }, context) => {
      if (!context.user) throw new Error('Not authenticated');
      const post = { id: String(posts.length + 1), ...input, authorId: context.user.id };
      posts.push(post);
      return post;
    },
  },
};

// Client (React): useMutation hook
import { useMutation, gql } from '@apollo/client';

const CREATE_POST = gql`
  mutation CreatePost($input: CreatePostInput!) {
    createPost(input: $input) {
      id
      title
    }
  }
`;

function CreatePostForm() {
  const [createPost, { loading, error }] = useMutation(CREATE_POST);

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await createPost({
        variables: { input: { title: 'My Post', content: 'Hello!' } },
      });
      console.log('Post created!');
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <button disabled={loading}>Create Post</button>
      {error && <p>Error: {error.message}</p>}
    </form>
  );
}

// 1. Cursor-based pagination (Relay connection pattern)
const typeDefs = `#graphql
  type PostConnection {
    edges: [PostEdge!]!
    pageInfo: PageInfo!
  }
  type PostEdge {
    node: Post!
    cursor: String!
  }
  type PageInfo {
    hasNextPage: Boolean!
    endCursor: String
  }
  type Query {
    posts(first: Int = 10, after: String): PostConnection!
  }
`;

// 2. Authentication via context
const server = new ApolloServer({ typeDefs, resolvers });
const { url } = await startStandaloneServer(server, {
  context: async ({ req }) => {
    const token = req.headers.authorization || '';
    const user = await verifyToken(token); // your JWT verification
    return { user }; // available in every resolver as context.user
  },
});

// 3. Authorization in resolvers
const resolvers = {
  Query: {
    // Only authenticated users can see their posts
    myPosts: (_, __, context) => {
      if (!context.user) throw new Error('Not authenticated');
      return posts.filter(p => p.authorId === context.user.id);
    },
  },
};

// 4. Depth limiting (prevent malicious nested queries)
import depthLimit from 'graphql-depth-limit';
const server = new ApolloServer({
  typeDefs,
  resolvers,
  validationRules: [depthLimit(5)], // max 5 levels of nesting
});
